    function ric($name, $size = 20, $class = 'ic') {
        return '<svg class="' . htmlspecialchars($class) . '" width="' . (int)$size . '" height="' . (int)$size . '" aria-hidden="true" focusable="false"><use href="#ic-' . htmlspecialchars($name) . '"></use></svg>';
    }

    function ric_text($text) {
        $map = [
            '🔥'=>'flame','📅'=>'cal','📆'=>'cal','🗓️'=>'cal','🏆'=>'trophy','🥇'=>'medal','🏅'=>'medal',
            '📢'=>'mega','🎓'=>'grad','👨‍🎓'=>'student','👨‍🏫'=>'teacher','🏫'=>'school',
            '💬'=>'chat','📍'=>'pin','⭐'=>'star','🌟'=>'star','👤'=>'user','📰'=>'news','📸'=>'cam','🎉'=>'star',
            '✅'=>'shield','🛡️'=>'shield','💰'=>'coins','🏛️'=>'bank','🌍'=>'globe','🌏'=>'globe','🌐'=>'globe','📚'=>'books',
            '🏢'=>'building','💡'=>'bulb','🎬'=>'film','❓'=>'help','🌙'=>'moon','☀️'=>'sun','🔐'=>'lock','📞'=>'phone','📭'=>'inbox',
            '🛠️'=>'wrench','🔧'=>'wrench','✉️'=>'mail','🔔'=>'bell','🏠'=>'home','📝'=>'pen','🤝'=>'handshake',
        ];
        foreach ($map as $e => $n) $text = str_replace($e, ric($n, 16), $text);
        return strip_emoji($text);
    }

    function strip_emoji($text) {
        return preg_replace('/[\x{1F000}-\x{1FAFF}\x{2600}-\x{27BF}\x{2B00}-\x{2BFF}\x{FE0F}\x{200D}\x{2190}-\x{21FF}\x{2700}-\x{27BF}]/u', '', $text);
    }

